using System;
using System.IO;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using CashflowChains.Economy;
using CashflowChains.Domain;
using LocalGame.Data;

public sealed class CC2EconomyTests {
 BalanceConfig config;
 [SetUp] public void Setup(){config=JsonUtility.FromJson<BalanceConfig>(File.ReadAllText(Path.Combine(Application.dataPath,"_Game/Data/CC2/balance-v1.json")));config.Validate();}
 CurrencyLedger Ledger()=>new CurrencyLedger(config,new EconomyState{AccountId="test-account"});
 [Test] public void ConfigDefinesFiniteCapsAndHasNoPositiveExchangeCycle(){Assert.AreEqual(28800,config.OfflineCapSeconds);Assert.AreEqual(10,config.Businesses.Length);Assert.False(config.EnabledFeatures.Any());config.Exchanges[1].Quantity=13;Assert.Throws<ArgumentException>(()=>config.Validate());}
 [Test] public void EvenTinyPositiveRationalExchangeCyclesAreRejected(){config.Exchanges[0].Cost=1000000000;config.Exchanges[0].Quantity=999999999;config.Exchanges[1].Cost=999999997;config.Exchanges[1].Quantity=999999998;Assert.Throws<ArgumentException>(()=>config.Validate());}
 [Test] public void IdempotentRetrySurvivesCatalogRevisionWithoutChangingOriginalGrant(){var l=Ledger();l.Execute("original","p","test","grant",1,t=>t.Grant("WOOD",10),_=>true);var saved=l.Snapshot;config.Revision++;var next=new CurrencyLedger(config,saved);next.Execute("original","p","test","grant",2,t=>t.Grant("WOOD",99),_=>true);Assert.AreEqual(10,next.Snapshot.Amount("WOOD"));Assert.AreEqual(1,next.Snapshot.Revision);Assert.Throws<InvalidOperationException>(()=>next.Execute("original","changed","test","grant",2,t=>t.Grant("WOOD",99),_=>true));}
 [Test] public void MissingSustainableFreeSourceRejectsCatalog(){config.Sources=config.Sources.Where(x=>x.ItemId!="WOOD"||!x.Repeatable).ToArray();Assert.Throws<ArgumentException>(()=>config.Validate());}
 [Test] public void PurchasedGemsCannotExpireAndRoundScoreCannotBeAnItem(){config.Item("GEMS").CanExpire=true;Assert.Throws<ArgumentException>(()=>config.Validate());config.Item("GEMS").CanExpire=false;config.Item("CASH").Id="ROUND_SCORE";Assert.Throws<ArgumentException>(()=>config.Validate());}
 [Test] public void AtomicMultiItemFailureNeverChangesAnyBalance(){var l=Ledger();Assert.Throws<InvalidOperationException>(()=>l.Execute("bad","p","test","rollback",1,t=>{t.Grant("WOOD",5);t.Spend("CASH",1);},_=>true));Assert.Zero(l.Snapshot.Revision);Assert.Zero(l.Snapshot.Amount("WOOD"));Assert.Zero(l.Snapshot.Ledger.Count);}
 [Test] public void DurableFailureAndRedeliveryApplyExactlyOnce(){var l=Ledger();int writes=0;Action<EconomyTransaction> grant=t=>t.Grant("WOOD",10);Assert.Throws<InvalidOperationException>(()=>l.Execute("id","p","test","grant",1,grant,_=>false));l.Execute("id","p","test","grant",1,grant,_=>{writes++;return true;});l.Execute("id","p","test","grant",2,grant,_=>{writes++;return true;});Assert.AreEqual(10,l.Snapshot.Amount("WOOD"));Assert.AreEqual(1,writes);Assert.Throws<InvalidOperationException>(()=>l.Execute("id","changed","test","grant",2,grant,_=>true));}
 [Test] public void EarnedGemsAreSpentFirstAndPurchasedNeverSilentlyExpire(){var l=Ledger();l.Execute("g","grant","test","grant",1,t=>{t.Grant("GEMS",20);t.Grant("GEMS",90,BalanceOrigin.Purchased);},_=>true);l.Execute("s","spend","test","spend",2,t=>t.Spend("GEMS",25),_=>true);var b=l.Snapshot.Balances.Single();Assert.Zero(b.Earned);Assert.AreEqual(85,b.Purchased);l.Snapshot.Validate(config);}
 [Test] public void UnverifiedImportedPremiumCannotBeSpent(){var l=Ledger();l.Execute("e","escrow","test","migration",1,t=>t.Grant("GEMS",90,BalanceOrigin.ImportEscrow),_=>true);Assert.Zero(l.Snapshot.Amount("GEMS"));Assert.Throws<InvalidOperationException>(()=>l.Execute("s","spend","test","spend",2,t=>t.Spend("GEMS",1),_=>true));}
 [Test] public void LedgerRejectsChangedWalletMissingRowsAndClockRollback(){var l=Ledger();l.Execute("g","grant","test","grant",100,t=>t.Grant("CASH",80),_=>true);var s=l.Snapshot;s.Balances[0].Earned++;Assert.Throws<ArgumentException>(()=>s.Validate(config));s=l.Snapshot;s.Ledger.Clear();Assert.Throws<ArgumentException>(()=>s.Validate(config));Assert.Throws<ArgumentException>(()=>l.Execute("x","p","test","grant",99,t=>t.Grant("CASH",1),_=>true));}
 [Test] public void BalanceOverflowAndCapFailureRollBackWholeCommand(){var l=Ledger();Assert.Throws<InvalidOperationException>(()=>l.Execute("cap","p","test","grant",1,t=>t.Grant("WOOD",1000001),_=>true));Assert.Zero(l.Snapshot.Revision);Assert.Throws<OverflowException>(()=>l.Execute("overflow","p","test","grant",1,t=>{t.Grant("CASH",1);t.Grant("CASH",long.MaxValue);},_=>true));Assert.Zero(l.Snapshot.Revision);}
 [Test] public void SnapshotAndPersistenceCallbacksCannotMutateLiveBalances(){var l=Ledger();l.Execute("g","p","test","grant",1,t=>t.Grant("WOOD",10),s=>{s.Balances[0].Earned=0;return true;});var snapshot=l.Snapshot;snapshot.Balances[0].Earned=42;Assert.AreEqual(10,l.Snapshot.Amount("WOOD"));}
 [Test] public void LegacyPlanPreservesPaidOwnershipProgressAndBlueprintsWithoutGrantingVerifiedMoney(){var p=new Profile();p.Award(0,3,1120,"clear");p.ApplyPurchase("cc.gems.small","fixture-order");p.ApplyPurchase("cc.blueprint.4","fixture-blueprint");p.ApplyPurchase("cc.scenario.finance","fixture-finance");var original=JsonUtility.ToJson(p);var plan=LegacyMigration.Prepare(p,original,config);Assert.AreEqual(650,plan.CashEscrow);Assert.AreEqual(90,plan.GemEscrow);Assert.AreEqual(6,plan.BlueprintCapacity);Assert.That(plan.EntitlementClaims,Does.Contain("cc.scenario.finance"));plan.Stars[0]=0;Assert.AreEqual(3,p.Stars[0]);Assert.AreEqual(original,JsonUtility.ToJson(p));var l=Ledger();LegacyMigration.StageEscrow(plan,l,1,_=>true);LegacyMigration.StageEscrow(plan,l,1,_=>true);Assert.Zero(l.Snapshot.Amount("CASH"));Assert.AreEqual(1,l.Snapshot.Revision);Assert.AreEqual(90,l.Snapshot.Balances.Single(x=>x.ItemId=="GEMS").ImportEscrow);}
 [Test] public void InvalidOldBalancesDoNotBecomeValidNewImports(){var p=new Profile{Credits=100000};Assert.Throws<ArgumentException>(()=>LegacyMigration.Prepare(p,JsonUtility.ToJson(p),config));}
 [Test] public void SourceFinderNeverAdvertisesDisabledOrLockedRoutes(){var f=new SourceFinder(config);Assert.IsEmpty(f.Available("WOOD",3,new string[0]));Assert.IsEmpty(f.Available("WOOD",2,new[]{"empire"}));Assert.AreEqual(2,f.Available("WOOD",3,new[]{"empire"}).Length);Assert.IsEmpty(f.Available("GEAR_CORES",60,new[]{"empire"}));}
 [Test] public void EveryOriginalCertifiedScoreIsUnchangedByCC2RewardPolicy(){for(int i=0;i<104;i++){var mission=Campaign.Get(i);var q=RoundRewardPolicy.VerifyCertified(config,i,mission.Solution);Assert.AreEqual(new CityRun(i,mission.Solution.Copy()).Preview().Credits,q.RoundScore);Assert.AreEqual(3,q.Stars);Assert.That(q.Items.All(x=>x.ItemId!="ROUND_SCORE"));}}
 [Test] public void OneSuccessfulLevelCannotFarmCashThroughAnotherRoundOrLayout(){var l=Ledger();var board=Campaign.Get(0).Solution.Copy();RoundRewardPolicy.ClaimFirstClear(l,"test-account",0,board,config,1,_=>true);RoundRewardPolicy.ClaimFirstClear(l,"test-account",0,board,config,2,_=>true);Assert.AreEqual(80,l.Snapshot.Amount("CASH"));Assert.AreEqual(10,l.Snapshot.Amount("WOOD"));Assert.AreEqual(1,l.Snapshot.Amount("CHEST:bronze"));Assert.AreEqual(1,l.Snapshot.Revision);Assert.Throws<ArgumentException>(()=>RoundRewardPolicy.ClaimFirstClear(l,"another-account",0,board,config,3,_=>true));}
 [Test] public void LockedOrUnverifiedExpansionRewardsAreRejected(){var l=Ledger();Assert.Throws<InvalidOperationException>(()=>RoundRewardPolicy.ClaimFirstClear(l,"test-account",71,Campaign.Get(71).Solution,config,1,_=>true));Assert.Throws<InvalidOperationException>(()=>RoundRewardPolicy.ClaimFirstClear(l,"test-account",72,Campaign.Get(72).Solution,config,1,_=>true));Assert.Zero(l.Snapshot.Revision);}
 [Test] public void ForgedBoardEndowmentsAndFailureNeverGrantRewards(){var l=Ledger();var b=Campaign.Get(0).Solution.Copy();b.Nodes[1].InitialGoods=64;Assert.Throws<ArgumentException>(()=>RoundRewardPolicy.ClaimFirstClear(l,"test-account",0,b,config,1,_=>true));Assert.Throws<InvalidOperationException>(()=>RoundRewardPolicy.ClaimFirstClear(l,"test-account",0,Campaign.Get(0).Start,config,1,_=>true));Assert.Zero(l.Snapshot.Revision);}
 [Test] public void StackingAndTimeReductionHaveBoundedIntegerResults(){Assert.AreEqual(200,EconomyMath.WithBonus(100,50000,10000));Assert.AreEqual(30,EconomyMath.Duration(60,50000));Assert.AreEqual(1,EconomyMath.Duration(1,5000));Assert.Throws<OverflowException>(()=>EconomyMath.WithBonus(long.MaxValue,1000,10000));}
}
